    '/^restored into a scratch server: (\\d+) tables, (\\d+) audit entries$/u' => 'استُعيدت إلى خادم مؤقت: عدد الجداول {1}، وعدد قيود التدقيق {2}',
    '/^no backup found in (.+)$/u' => 'لم تُوجد نسخة احتياطية في {1}',
    '/^checksum of (.+) does not match$/u' => 'المجموع الاختباري (checksum) للملف {1} لا يطابق',
    '/^the scratch server did not start: (.*)$/u' => 'لم يبدأ الخادم المؤقت: {1}',
    '/^the dump did not load: (.*)$/u' => 'تعذّر تحميل ملف التفريغ: {1}',
    '/^only (\\d+) tables were restored$/u' => 'لم تُستعَد سوى {1} من الجداول',
    '/^the audit-chain entry #(\\d+) recorded at backup time is missing or different in the restored data$/u' => 'قيد سلسلة التدقيق #{1} المسجَّل وقت النسخ الاحتياطي مفقود أو مختلف في البيانات المستعادة',
    '/^(\\d+) evidence file\\(s\\) listed in the database are not in the evidence archive$/u' => '{1} من ملفات الشواهد المدرجة في قاعدة البيانات غير موجودة في أرشيف الشواهد',

    // ---------------------------------------------------------------- Security evidence report
    '/^(\\d+) entries verified$/u' => 'تم التحقق من {1} من القيود',
    '/^(\\d+) of (\\d+) password-using$/u' => '{1} من {2} ممن يدخلون بكلمة المرور',
    '/^(University single sign-on with \\S+ \\(OpenID Connect with PKCE, signed ID tokens and nonce\\)\\. Two-step verification for these sign-ins is the identity provider\'s policy(?:; SAQF also refuses ID tokens that do not report it| and is not enforced by SAQF; university IT must confirm it)\\.|University single sign-on is not configured: everyone signs in with a SAQF password\\.) Passwords: hashed with (Argon2id|bcrypt), at least (\\d+) characters, common and guessable passwords refused\\. Two-step verification for password sign-in is required for: nobody\\. Lockout after (\\d+) failures and per-address throttling\\.$/u' => '{t1} كلمات المرور: تُجزَّأ بخوارزمية {2}، وطولها {3} أحرف على الأقل، وتُرفض كلمات المرور الشائعة والمتوقعة. والتحقق بخطوتين عند الدخول بكلمة المرور مطلوب من: لا أحد. والقفل بعد {4} محاولات فاشلة، مع تقييد لكل عنوان.',
    '/^(University single sign-on with \\S+ \\(OpenID Connect with PKCE, signed ID tokens and nonce\\)\\. Two-step verification for these sign-ins is the identity provider\'s policy(?:; SAQF also refuses ID tokens that do not report it| and is not enforced by SAQF; university IT must confirm it)\\.|University single sign-on is not configured: everyone signs in with a SAQF password\\.) Passwords: hashed with (Argon2id|bcrypt), at least (\\d+) characters, common and guessable passwords refused\\. Two-step verification for password sign-in is required for: administrators\\. Lockout after (\\d+) failures and per-address throttling\\.$/u' => '{t1} كلمات المرور: تُجزَّأ بخوارزمية {2}، وطولها {3} أحرف على الأقل، وتُرفض كلمات المرور الشائعة والمتوقعة. والتحقق بخطوتين عند الدخول بكلمة المرور مطلوب من: المسؤولين. والقفل بعد {4} محاولات فاشلة، مع تقييد لكل عنوان.',
    '/^(University single sign-on with \\S+ \\(OpenID Connect with PKCE, signed ID tokens and nonce\\)\\. Two-step verification for these sign-ins is the identity provider\'s policy(?:; SAQF also refuses ID tokens that do not report it| and is not enforced by SAQF; university IT must confirm it)\\.|University single sign-on is not configured: everyone signs in with a SAQF password\\.) Passwords: hashed with (Argon2id|bcrypt), at least (\\d+) characters, common and guessable passwords refused\\. Two-step verification for password sign-in is required for: everyone\\. Lockout after (\\d+) failures and per-address throttling\\.$/u' => '{t1} كلمات المرور: تُجزَّأ بخوارزمية {2}، وطولها {3} أحرف على الأقل، وتُرفض كلمات المرور الشائعة والمتوقعة. والتحقق بخطوتين عند الدخول بكلمة المرور مطلوب من: الجميع. والقفل بعد {4} محاولات فاشلة، مع تقييد لكل عنوان.',
    '/^University single sign-on with (\\S+) \\(OpenID Connect with PKCE, signed ID tokens and nonce\\)\\. Two-step verification for these sign-ins is the identity provider\'s policy; SAQF also refuses ID tokens that do not report it\\.$/u' => 'الدخول الموحّد للجامعة مع {1} (OpenID Connect مع PKCE ورموز هوية موقّعة وnonce). والتحقق بخطوتين في عمليات الدخول هذه من سياسة مزوّد الهوية؛ ويرفض SAQF أيضاً رموز الهوية التي لا تفيد بإجرائه.',
    '/^University single sign-on with (\\S+) \\(OpenID Connect with PKCE, signed ID tokens and nonce\\)\\. Two-step verification for these sign-ins is the identity provider\'s policy and is not enforced by SAQF; university IT must confirm it\\.$/u' => 'الدخول الموحّد للجامعة مع {1} (OpenID Connect مع PKCE ورموز هوية موقّعة وnonce). والتحقق بخطوتين في عمليات الدخول هذه من سياسة مزوّد الهوية ولا يفرضه SAQF؛ وعلى تقنية المعلومات في الجامعة التأكد منه.',
    '/^Anti-forgery tokens on every change, re-confirmation of identity for sensitive administrator actions, a stated reason for access changes\\. Access review: (\\d+) of (\\d+) accounts confirmed within (\\d+) days\\.$/u' => 'رموز الحماية من التزوير (anti-forgery) في كل تغيير، وإعادة تأكيد الهوية في إجراءات المسؤولين الحساسة، وذكر السبب عند تغيير الصلاحيات. مراجعة الصلاحيات: أُكّدت صلاحيات {1} من {2} حسابات خلال {3} يوماً.',
    '/^Important actions go into a hash-chained audit log: tamper-evident, not tamper-proof\\. Verifying the chain reveals an edited or deleted entry \\(verified intact just now, (\\d+) entries\\); it cannot stop someone with database administrator rights from changing rows\\. Append-only database triggers: installed\\.$/u' => 'تُسجَّل الإجراءات المهمة في سجل تدقيق مترابط بسلسلة تجزئة: يكشف العبث ولا يمنعه. ويكشف التحقق من السلسلة أي قيد عُدّل أو حُذف (تم التحقق قبل لحظات وهي سليمة، {1} من القيود)؛ لكنه لا يمنع من يملك صلاحيات مسؤول قاعدة البيانات من تغيير السجلات. مشغّلات قاعدة البيانات للإضافة فقط: مثبّتة.',
    '/^Important actions go into a hash-chained audit log: tamper-evident, not tamper-proof\\. Verifying the chain reveals an edited or deleted entry \\(verified intact just now, (\\d+) entries\\); it cannot stop someone with database administrator rights from changing rows\\. Append-only database triggers: NOT found\\.$/u' => 'تُسجَّل الإجراءات المهمة في سجل تدقيق مترابط بسلسلة تجزئة: يكشف العبث ولا يمنعه. ويكشف التحقق من السلسلة أي قيد عُدّل أو حُذف (تم التحقق قبل لحظات وهي سليمة، {1} من القيود)؛ لكنه لا يمنع من يملك صلاحيات مسؤول قاعدة البيانات من تغيير السجلات. مشغّلات قاعدة البيانات للإضافة فقط: غير موجودة.',
    '/^Important actions go into a hash-chained audit log: tamper-evident, not tamper-proof\\. Verifying the chain reveals an edited or deleted entry \\(BROKEN — see above\\); it cannot stop someone with database administrator rights from changing rows\\. Append-only database triggers: installed\\.$/u' => 'تُسجَّل الإجراءات المهمة في سجل تدقيق مترابط بسلسلة تجزئة: يكشف العبث ولا يمنعه. ويكشف التحقق من السلسلة أي قيد عُدّل أو حُذف (منقطعة — انظر أعلاه)؛ لكنه لا يمنع من يملك صلاحيات مسؤول قاعدة البيانات من تغيير السجلات. مشغّلات قاعدة البيانات للإضافة فقط: مثبّتة.',
    '/^Important actions go into a hash-chained audit log: tamper-evident, not tamper-proof\\. Verifying the chain reveals an edited or deleted entry \\(BROKEN — see above\\); it cannot stop someone with database administrator rights from changing rows\\. Append-only database triggers: NOT found\\.$/u' => 'تُسجَّل الإجراءات المهمة في سجل تدقيق مترابط بسلسلة تجزئة: يكشف العبث ولا يمنعه. ويكشف التحقق من السلسلة أي قيد عُدّل أو حُذف (منقطعة — انظر أعلاه)؛ لكنه لا يمنع من يملك صلاحيات مسؤول قاعدة البيانات من تغيير السجلات. مشغّلات قاعدة البيانات للإضافة فقط: غير موجودة.',
    '/^a virus scanner is configured \\((\\d+) of (\\d+) stored files have a recorded clean scan\\)\\.$/u' => 'برنامج فحص الفيروسات مُعدّ ({1} من {2} ملفات مخزَّنة لها فحص سليم مسجَّل).',
    '/^NO virus scanner is configured, so files are not scanned for malware \\((\\d+) stored\\)\\.$/u' => 'لا يوجد برنامج لفحص الفيروسات، لذا لا تُفحص الملفات بحثاً عن البرمجيات الخبيثة ({1} مخزَّنة).',
    '/^Student identifiers from every grade source are replaced by keyed one-way pseudonyms before storage; no student names are kept\\. Application key: (.+?) Stored secrets are encrypted with AES-256-GCM\\. Uploaded evidence is checked by type and content and stored outside the web server; (a virus scanner is configured \\(\\d+ of \\d+ stored files have a recorded clean scan\\)\\.|NO virus scanner is configured, so files are not scanned for malware \\(\\d+ stored\\)\\.) Backups: (.+)$/u' => 'تُستبدل معرّفات الطلاب من كل مصدر للدرجات بأسماء مستعارة أحادية الاتجاه بمفتاح سري قبل التخزين؛ ولا تُحفظ أسماء الطلاب. مفتاح التطبيق: {t1} وتُشفَّر الأسرار المخزنة بـ AES-256-GCM. وتُفحص الشواهد المرفوعة بحسب نوعها ومحتواها وتُخزَّن خارج خادم الويب؛ {t2} النسخ الاحتياطي: {t3}',
    '/^(This report was served over HTTPS \\(HSTS sent\\)\\.|This report was NOT served over HTTPS\\.) Strict Content-Security-Policy with no inline scripts, frame blocking, SameSite=Strict HttpOnly cookies, idle \\((\\d+) min\\) and absolute \\((\\d+) h\\) session limits, sessions listed and revocable by their owner\\.$/u' => '{t1} سياسة أمان محتوى صارمة (Content-Security-Policy) بلا نصوص برمجية مضمّنة، ومنع التضمين في الإطارات، وملفات تعريف ارتباط SameSite=Strict وHttpOnly، وحدّان للجلسة: الخمول ({2} دقيقة) والمدة المطلقة ({3} ساعة)، وجلسات يعرضها صاحبها ويمكنه إنهاؤها.',
    '/^Failing connectors, a stalled scheduler, missing or incomplete backups, a broken audit chain, a failed self-test, overdue access review, undeliverable mail, blocked malware and password guessing raise alerts in SAQF, by e-mail and to the configured webhook\\.$/u' => 'تعطّل الموصّلات، وتوقف المجدول، وغياب النسخ الاحتياطية أو عدم اكتمالها، وانقطاع سلسلة التدقيق، وفشل الاختبار الذاتي، وتأخر مراجعة الصلاحيات، وتعذّر تسليم البريد، وحجب البرمجيات الخبيثة، وتخمين كلمات المرور — كلها ترفع تنبيهات داخل SAQF، وبالبريد الإلكتروني، وإلى webhook المُعدّ.',
    '/^Failing connectors, a stalled scheduler, missing or incomplete backups, a broken audit chain, a failed self-test, overdue access review, undeliverable mail, blocked malware and password guessing raise alerts in SAQF, by e-mail \\(no webhook configured\\)\\.$/u' => 'تعطّل الموصّلات، وتوقف المجدول، وغياب النسخ الاحتياطية أو عدم اكتمالها، وانقطاع سلسلة التدقيق، وفشل الاختبار الذاتي، وتأخر مراجعة الصلاحيات، وتعذّر تسليم البريد، وحجب البرمجيات الخبيثة، وتخمين كلمات المرور — كلها ترفع تنبيهات داخل SAQF، وبالبريد الإلكتروني (لا webhook مُعدّ).',
    '/^Failing connectors, a stalled scheduler, missing or incomplete backups, a broken audit chain, a failed self-test, overdue access review, undeliverable mail, blocked malware and password guessing raise alerts in SAQF \\(e-mail not configured\\) and to the configured webhook\\.$/u' => 'تعطّل الموصّلات، وتوقف المجدول، وغياب النسخ الاحتياطية أو عدم اكتمالها، وانقطاع سلسلة التدقيق، وفشل الاختبار الذاتي، وتأخر مراجعة الصلاحيات، وتعذّر تسليم البريد، وحجب البرمجيات الخبيثة، وتخمين كلمات المرور — كلها ترفع تنبيهات داخل SAQF (البريد الإلكتروني غير مُعدّ)، وإلى webhook المُعدّ.',
    '/^Failing connectors, a stalled scheduler, missing or incomplete backups, a broken audit chain, a failed self-test, overdue access review, undeliverable mail, blocked malware and password guessing raise alerts in SAQF \\(e-mail not configured\\) \\(no webhook configured\\)\\.$/u' => 'تعطّل الموصّلات، وتوقف المجدول، وغياب النسخ الاحتياطية أو عدم اكتمالها، وانقطاع سلسلة التدقيق، وفشل الاختبار الذاتي، وتأخر مراجعة الصلاحيات، وتعذّر تسليم البريد، وحجب البرمجيات الخبيثة، وتخمين كلمات المرور — كلها ترفع تنبيهات داخل SAQF (البريد الإلكتروني غير مُعدّ، ولا webhook مُعدّ).',
    '/^Report fingerprint (\\S+): generating this report is itself entered in the audit log under this code, so a printed copy can be matched to the system\\. This is a statement of how the system is configured and behaving, not a compliance certification\\.$/u' => 'بصمة التقرير {1}: يُسجَّل إنشاء هذا التقرير نفسه في سجل التدقيق بهذا الرمز، فيمكن مطابقة النسخة المطبوعة مع النظام. وهذا بيان لكيفية إعداد النظام وسلوكه، وليس شهادة امتثال.',

    // ---------------------------------------------------------------- Security incidents
    '/^Incident #(\\d+) registered\\.$/u' => 'سُجّل الحادث #{1}.',
    '/^Past the (\\d+)-hour window \\(([\\d.]+) h ago\\)$/u' => 'انتهت مهلة {1} ساعة (قبل {2} ساعة)',
    '/^([\\d.]+) h left of (\\d+)$/u' => 'المتبقي {1} ساعة من {2}',
    '/^until (\\d{1,2} \\S+ \\d{4}, \\d\\d:\\d\\d)$/u' => 'حتى {t1}',
    '/^about (\\d+) people$/u' => 'نحو {1} من الأشخاص',
    '/^registered by (.+)$/u' => 'سجّله {1}',
    '/^detected (\\d{1,2} \\S+ \\d{4}, \\d\\d:\\d\\d)$/u' => 'اكتُشف في {t1}',
    '/^Incident registered by (.+)$/u' => 'سجّل {1} الحادث',
    '/^This register supports the university\'s incident process; it does not replace it\\. For incidents involving personal data, the Saudi Personal Data Protection Law is described in the sources we reviewed as requiring notification of the competent authority \\(SDAIA\\) within (\\d+) hours of becoming aware of a breach likely to cause harm\\. Whether that applies to a given incident is for the data protection officer or legal counsel to decide\\. SAQF never contacts an authority or any person by itself\\.$/u' => 'يدعم هذا السجل إجراءات الجامعة في التعامل مع الحوادث ولا يحل محلها. وفيما يخص الحوادث التي تتضمن بيانات شخصية، يرد في المصادر التي راجعناها أن نظام حماية البيانات الشخصية في المملكة يوجب إشعار الجهة المختصة (SDAIA – الهيئة السعودية للبيانات والذكاء الاصطناعي) خلال {1} ساعة من العلم بحدوث اختراق يُحتمل أن يسبب ضرراً. أما انطباق ذلك على حادث بعينه فيقرره مسؤول حماية البيانات أو المستشار القانوني. ولا يتصل SAQF أبداً بأي جهة أو شخص من تلقاء نفسه.',
    '/^Security incident #(\\d+) registered \\(low\\): (.+)$/u' => 'سُجّل الحادث الأمني #{1} (الخطورة: منخفضة): {2}',
    '/^Security incident #(\\d+) registered \\(medium\\): (.+)$/u' => 'سُجّل الحادث الأمني #{1} (الخطورة: متوسطة): {2}',
    '/^Security incident #(\\d+) registered \\(high\\): (.+)$/u' => 'سُجّل الحادث الأمني #{1} (الخطورة: عالية): {2}',
    '/^Security incident #(\\d+) registered \\(critical\\): (.+)$/u' => 'سُجّل الحادث الأمني #{1} (الخطورة: حرجة): {2}',
    '/^Security incident #(\\d+) registered \\(low, personal data involved\\): (.+)$/u' => 'سُجّل الحادث الأمني #{1} (الخطورة: منخفضة، ويتضمن بيانات شخصية): {2}',
    '/^Security incident #(\\d+) registered \\(medium, personal data involved\\): (.+)$/u' => 'سُجّل الحادث الأمني #{1} (الخطورة: متوسطة، ويتضمن بيانات شخصية): {2}',
    '/^Security incident #(\\d+) registered \\(high, personal data involved\\): (.+)$/u' => 'سُجّل الحادث الأمني #{1} (الخطورة: عالية، ويتضمن بيانات شخصية): {2}',
    '/^Security incident #(\\d+) registered \\(critical, personal data involved\\): (.+)$/u' => 'سُجّل الحادث الأمني #{1} (الخطورة: حرجة، ويتضمن بيانات شخصية): {2}',
    '/^Security incident #(\\d+): contained by (.+)$/u' => 'الحادث الأمني #{1}: تم احتواؤه (بواسطة {2})',
    '/^Security incident #(\\d+): authority notified by (.+)$/u' => 'الحادث الأمني #{1}: أُشعرت الجهة المختصة (بواسطة {2})',
    '/^Security incident #(\\d+): subjects notified by (.+)$/u' => 'الحادث الأمني #{1}: أُبلغ أصحاب البيانات (بواسطة {2})',
    '/^Security incident #(\\d+): note by (.+)$/u' => 'الحادث الأمني #{1}: أُضيفت ملاحظة (بواسطة {2})',
    '/^Security incident #(\\d+): closed by (.+)$/u' => 'الحادث الأمني #{1}: أُغلق (بواسطة {2})',
    '/^(#\\d+ .+? \\([\\d.]+ h left\\)); (#\\d+ .+)$/u' => '{t1}؛ {t2}',
    '/^(#\\d+ .+) \\(([\\d.]+) h left\\)$/u' => '{1} (المتبقي {2} ساعة)',
    '/^(.+)\\. The data protection officer must decide now whether the authority has to be notified, and record it in Security incidents\\.$/u' => '{1}. يجب أن يقرر مسؤول حماية البيانات الآن ما إذا كان لا بد من إشعار الجهة المختصة، وأن يسجّل ذلك في «حوادث الأمان».',
    '/^(.+)\\. Ask the data protection officer to decide on notification and record it in Security incidents\\.$/u' => '{t1}. اطلب من مسؤول حماية البيانات البتّ في الإشعار وتسجيل ذلك في «حوادث الأمان».',

    // ---------------------------------------------------------------- Audit-chain witnesses
    '/^Audit chain witnessed at entry (\\d+) \\(sent by e-mail\\)$/u' => 'أُخذ إشهاد لسلسلة التدقيق عند القيد {1} (أُرسل بالبريد الإلكتروني)',
    '/^Audit chain witnessed at entry (\\d+) \\(sent by webhook\\)$/u' => 'أُخذ إشهاد لسلسلة التدقيق عند القيد {1} (أُرسل عبر webhook)',
    '/^Audit chain witnessed at entry (\\d+) \\(sent by e-mail and webhook\\)$/u' => 'أُخذ إشهاد لسلسلة التدقيق عند القيد {1} (أُرسل بالبريد الإلكتروني وعبر webhook)',
    '/^Audit chain witnessed at entry (\\d+) \\(NOT sent outside the server: no e-mail or webhook is configured\\)$/u' => 'أُخذ إشهاد لسلسلة التدقيق عند القيد {1} (لم يُرسل إلى خارج الخادم: لا بريد إلكتروني ولا webhook مُعدّ)',
    '/^Entry #(\\d+), witnessed at (\\S+), no longer exists: the activity log has been truncated or replaced\\.$/u' => 'القيد #{1}، الذي أُشهد عليه في {2}، لم يعد موجوداً: فقد اقتُطع جزء من سجل النشاط أو استُبدل.',
    '/^Entry #(\\d+) has a different hash than the one witnessed at (\\S+): history up to that point was rewritten\\.$/u' => 'للقيد #{1} تجزئة مختلفة عن التي أُشهد عليها في {2}: أُعيدت كتابة السجل حتى تلك النقطة.',
    '/^Witnessed at (\\S+), entries up to #(\\d+) were (\\d+), now (\\d+): entries were removed or inserted\\.$/u' => 'عند الإشهاد في {1} كان عدد القيود حتى #{2} هو {3}، وهو الآن {4}: حُذفت قيود أو أُدرجت قيود.',
    '/^Entries up to #(\\d+) are unchanged since (\\S+)\\.$/u' => 'القيود حتى #{1} لم تتغير منذ {2}.',
    '/^Entries up to #(\\d+) are unchanged since (\\S+) \\(note: this witness names another installation, (\\S+)\\)\\.$/u' => 'القيود حتى #{1} لم تتغير منذ {2} (ملاحظة: يشير هذا الإشهاد إلى تثبيت آخر هو {3}).',
